-- M0.4 (setup wizard and `toa core install`). Generated by drizzle-kit (the two tables), with step 3 added by hand.
--
-- 1. admin_notice: site-wide notices for the dashboard (the first is «e-post ble hoppet over», shown in M0.5).
-- 2. site_secret: the setup token's hash and the backup recovery key's verifier, never in `setting`.
--    The app role gets DML on both from the default privileges in init.sql, which is what the install service needs.
CREATE TABLE "admin_notice" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7() NOT NULL,
	"key" text NOT NULL,
	"level" text NOT NULL,
	"message_key" text NOT NULL,
	"data" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"capability" text DEFAULT 'manage_options' NOT NULL,
	"is_dismissible" boolean DEFAULT true NOT NULL,
	"dismissed_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"modified_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "uq_admin_notice_key" UNIQUE("key"),
	CONSTRAINT "ck_admin_notice_level" CHECK ("admin_notice"."level" in ('error', 'warning', 'success', 'info')),
	CONSTRAINT "ck_admin_notice_key" CHECK ("admin_notice"."key" ~ '^[a-z0-9_.-]+$'),
	CONSTRAINT "ck_admin_notice_message_key" CHECK ("admin_notice"."message_key" <> '')
);
--> statement-breakpoint
CREATE TABLE "site_secret" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7() NOT NULL,
	"purpose" text NOT NULL,
	"secret_hash" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"modified_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "uq_site_secret_purpose" UNIQUE("purpose"),
	CONSTRAINT "ck_site_secret_purpose" CHECK ("site_secret"."purpose" in ('setup_token', 'backup_recovery_key')),
	CONSTRAINT "ck_site_secret_secret_hash" CHECK ("site_secret"."secret_hash" ~ '^[0-9a-f]{64}$')
);

