-- 3. A database that v0.3.0 or older already uses has no `installed` setting yet, and seedCore() (which runs after the
--    migrations) would insert `installed = false`: the next start would then send every page to /setup and offer to
--    make a second administrator on a site that has one. Where an active administrator exists, the site counts as
--    installed: this writes `installed = true` and `installed_at = now` before the seed, which then leaves the rows
--    alone (ON CONFLICT DO NOTHING). No default content is made for such a site. On a new database there is no account
--    here and nothing happens; the install sets the flag. Written to audit_log as the system, source setup.
WITH admins AS (
  SELECT 1
    FROM public.account AS a
    JOIN public.account_role AS ar ON ar.account_id = a.id
    JOIN public.role AS r ON r.id = ar.role_id
   WHERE r.slug = 'administrator'
     AND a.status = 'active'
   LIMIT 1
), stamp AS (
  SELECT pg_catalog.to_jsonb(pg_catalog.to_char(pg_catalog.now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')) AS at
), changed AS (
  INSERT INTO public.setting (key, value)
  SELECT v.key, v.value
    FROM admins, stamp,
         LATERAL (VALUES ('installed', 'true'::jsonb), ('installed_at', stamp.at)) AS v (key, value)
  ON CONFLICT (key) DO NOTHING
  RETURNING key, value
)
INSERT INTO public.audit_log (actor_type, actor, action, object_type, object_id, old_value, new_value, reason, source)
SELECT 'system', 'migration 0005_install_state', 'setting.updated', 'setting', changed.key, NULL, changed.value,
       'a site with an administrator from before M0.4 counts as installed', 'setup'
  FROM changed;
